constraints:
1 <= K <= 10^{3}

expected time complexity: O(nk Logk)
expected auxiliary space: O(k)

standard_solution_code:
import heapq

class Solution:

	def mergeKLists(self, arr, K):
		dummy = Node(-1)
		heap = []
		for i in arr:
			while i:
				heapq.heappush(heap, i.data)
				i = i.next
		ptr = dummy
		while heap:
			temp = Node(heapq.heappop(heap))
			ptr.next = temp
			ptr = ptr.next
		ptr.next = None
		return dummy.next
